CREATE TABLE public.identities (id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, deleted_at timestamptz, version integer NOT NULL DEFAULT 0, user_id uuid NOT NULL REFERENCES public.users(id), type varchar(16) NOT NULL CHECK (type IN ('company','bureau','agent','school','teacher','student','parent')), org_id uuid NOT NULL, department_id uuid, ref_id uuid, title text, status smallint NOT NULL DEFAULT 1 CHECK (status IN (0,1)), sort integer NOT NULL DEFAULT 0);
